import React, { useState } from 'react';
import { FaSearch, FaChevronDown, FaChevronUp } from 'react-icons/fa';
import { colors } from '../../styles/theme';

function Recherche({ 
  valeur, 
  onChange, 
  placeholder = "Rechercher...",
  onToggleAvance,
  showAvance = false,
  texteAvance = "Recherche avancée"
}) {
  const [isFocused, setIsFocused] = useState(false);

  return (
    <div 
      className="rounded-lg shadow-md mb-4 transition-all duration-300"
      style={{ 
        backgroundColor: colors.globalLight,
        borderLeft: isFocused ? `4px solid ${colors.primaryColor}` : '4px solid transparent',
        padding: '16px 20px'
      }}
    >
      <div className="flex flex-col md:flex-row md:items-center md:justify-between">
        <div className="flex-1 mb-2 md:mb-0 md:mr-4">
          <div className="relative">
            <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
              <FaSearch style={{ color: isFocused ? colors.primaryColor : colors.textLight }} />
            </div>
            <input
              type="text"
              placeholder={placeholder}
              value={valeur}
              onChange={onChange}
              onFocus={() => setIsFocused(true)}
              onBlur={() => setIsFocused(false)}
              className="w-full pl-10 pr-4 py-3 rounded-md focus:outline-none transition-all duration-200"
              style={{ 
                border: `1px solid ${isFocused ? colors.primaryColor : colors.borderColor}`,
                backgroundColor: isFocused ? colors.globalLight : colors.inputBg,
                boxShadow: isFocused ? `0 0 0 3px ${colors.highlightColor}` : 'none',
                color: colors.textColor
              }}
            />
          </div>
        </div>
        {onToggleAvance && (
          <button
            onClick={onToggleAvance}
            className="flex items-center transition-colors duration-200 px-4 py-2 rounded-md"
            style={{ 
              color: colors.primaryColor,
              backgroundColor: showAvance ? colors.highlightColor : 'transparent'
            }}
          >
            {showAvance ? <FaChevronUp className="mr-2" /> : <FaChevronDown className="mr-2" />}
            {showAvance ? 'Masquer' : 'Afficher'} {texteAvance}
          </button>
        )}
      </div>
    </div>
  );
}

export default Recherche;
